from .exception import MultipleFilesError
from .fsmaccess import FsmAccess, EstablishSSHinMethodContext
from lxml import etree


class EnbFsmAccess(FsmAccess):

    def __init__(self, connection_manager, fsm_services):
        """ Prepare connection to Fsm.

        :param ConnectionManager connection_manager:        Connection Manager (e.g. ssh, telnet).
        :param Fsmservices fsm_services:                    Fsm services.

        """
        super(EnbFsmAccess, self).__init__(connection_manager)
        self._fsm_service = fsm_services

    @EstablishSSHinMethodContext
    def get_fsm_sw_version(self, partition='active'):
        """Get Fsm software version.

        :param string partition:        Partition type, default: active.

        :return:                        Fsm software version.
        :rtype:                         string
        """
        return self._get_fsm_sw_version(partition)

    @EstablishSSHinMethodContext
    def get_enb_scfc(self, dst, partition='active', env='fsmf'):
        """Copy SCFC.xml from defined partition of eNB to specified localization on PC

        :param string dst:              Destination file path.
        :param string partition:        Partition type, default: active.
        :param string env:              Testline environment (e.g. fsm, fzm), default: fsmf.

        :return:                        Source and destination path.
        :rtype:                         tuple

        :raise:                         Exception if more than one SCFC exists on FSM.
        """
        partition_path = self._get_partition_path(partition)
        scfc_name = self._get_scfc_name(partition_path, env)
        scfc_file_path = self._get_scfc_full_path(partition_path, scfc_name, env)
        return self._get_file(src=scfc_file_path, dst=dst)

    @EstablishSSHinMethodContext
    def put_enb_scfc(self, src, partition='active', env='fsmf', ignore_multiple_scfc=False):
        """Copy SCFC.xml from specified localization to defined partition of eNB.

        :param string  src:                     Source file path.
        :param string  partition:               Partition type, default: active.
        :param string  env:                     Testline environment (e.g. fsm, fzm), default: fsmf.
        :param boolean ignore_multiple_scfc     Flag to ignore the MultipleFilesError exception, default: False.

        :return:                                Source and destination path.
        :rtype:                                 tuple

        :raise:                                 Exception if more than one SCFC exists on FSM.
        """
        partition_path = self._get_partition_path(partition)
        scfc_file = self._execute_ssh_command(self._find_scfc_paths(partition_path, env) + " 2>/dev/null || true")

        if not ignore_multiple_scfc and not self._is_only_one_file(scfc_file):
            raise MultipleFilesError("Multiple SCFC files found.")

        if partition in ['passive', 'planned']:
            self._make_writeable_passive_partition()

        return self._put_file(src=src, dst=self._build_scfc_path(partition_path, scfc_file, env))

    @EstablishSSHinMethodContext
    def get_enb_hwf(self, dst, partition='active'):
        """Copy hwf.xml from defined partition of eNB to specified localization on PC.

        :param string dst:              Path to destination directory.
        :param string partition:        Partition type, default: active.

        :return:                        Source and destination path.
        :rtype:                         tuple
        """
        partition_path = self._get_partition_path(partition)
        return self._get_file(src='{}/config/hwf.bin.gz'.format(partition_path), dst=dst)

    @EstablishSSHinMethodContext
    def put_enb_hwf(self, src, partition='active'):
        """Copy hwf.xml from specified localization to defined partition of eNB.

        :param string src:              Source file path.
        :param string partition:        Partition type, default: active.

        :return:                        Source and destination path.
        :rtype:                         tuple
        """
        partition_path = self._get_partition_path(partition)
        if partition in ['passive', 'planned']:
            self._make_writeable_passive_partition()
        return self._put_file(src=src, dst='{}/config/hwf.bin.gz'.format(partition_path))

    @EstablishSSHinMethodContext
    def get_enb_targetbd(self, dst, partition='active'):
        """Copy TargetBD*.xml from defined partition of eNB to specified localization on PC.

        :param string dst:              Path to destination directory.
        :param string partition:        Partition type, default: active.

        :return:                        Source and destination path
        :rtype:                         tuple
        """
        partition_path = self._get_partition_path(partition)
        swversion = self._get_fsm_sw_version(partition)
        return self._get_file(src='{}/TargetBD_{}*.xml'.format(partition_path, swversion), dst=dst)

    @EstablishSSHinMethodContext
    def put_enb_targetbd(self, src, partition='active'):
        """Copy TargetBD*.xml from specified localization to defined partition of eNB.

        :param string src:              Source file path.
        :param string partition:        Partition type, default: active.

        :return:                        Source and destination path.
        :rtype:                         tuple
        """
        partition_path = self._get_partition_path(partition)
        swversion = self._get_fsm_sw_version(partition)
        if partition in ['passive', 'planned']:
            self._make_writeable_passive_partition()
        return self._put_file(src=src, dst='{}/TargetBD_{}.xml'.format(partition_path, swversion))

    @EstablishSSHinMethodContext
    def get_enb_swconfig(self, dst, partition='active'):
        """Copy swconfig.txt file from defined partition of eNB to specified localization on PC.

        :param string dst:          Destination directory path.
        :param string partition:    Partition type, default: active.

        :return:                    Source and destination path.
        :rtype:                     tuple
        """
        partition_path = self._get_partition_path(partition)
        return self._get_file(src='{}/swconfig.txt'.format(partition_path), dst=dst)

    @EstablishSSHinMethodContext
    def put_enb_swconfig(self, src, partition='active'):
        """Copy swconfig.txt file from specified localization to defined partition of eNB.

        :param string src:              Source file path.
        :param string partition:        Partition type, default: active.

        :return:                        Source and destination path.
        :rtype:                         tuple
        """
        partition_path = self._get_partition_path(partition)
        if partition in ['passive', 'planned']:
            self._make_writeable_passive_partition()
        return self._put_file(src=src, dst='{}/swconfig.txt'.format(partition_path))

    @EstablishSSHinMethodContext
    def get_enb_filedirectory(self, dst, partition='active'):
        """Copy FileDirectory.xml file from defined partition of eNB to specified localization on PC.

        :param string dst:              Path to destination directory.
        :param string partition:        Partition type, default: active.

        :return:                        Source and destination path.
        :rtype:                         tuple
        """
        partition_path = self._get_partition_path(partition)
        return self._get_file(src='{}/FileDirectory.xml'.format(partition_path), dst=dst)

    @EstablishSSHinMethodContext
    def put_enb_filedirectory(self, src, partition='active'):
        """Copy FileDirectory.xml file from specified localization to defined partition of eNB.

        :param string src:              Source  path file.
        :param string partition:        Partition type, default: active.

        :return:                        Source and destination path.
        :rtype:                         tuple
        """
        partition_path = self._get_partition_path(partition)
        if partition in ['passive', 'planned']:
            self._make_writeable_passive_partition()
        return self._put_file(src=src, dst='{}/FileDirectory.xml'.format(partition_path))

    @EstablishSSHinMethodContext
    def set_writeable_enb_passive_partition(self):
        """Set read-write permission mode for eNB passive partition."""
        self._make_writeable_passive_partition()

    def enable_ssh(self, timeout=0):
        """Enable SSH services on FSM.

        :param integer timeout        Timeout in enabling SSH
        """
        return self._fsm_service.enable_ssh(timeout=timeout)

    def enable_rnd_ports(self):
        """Enable R&D ports on FSM."""
        return self._fsm_service.enable_rnd_ports()

    def remove_trs_configuration(self):
        """Remove TRS configuration."""
        return self._fsm_service.remove_trs_configuration()

    def _build_scfc_path(self, partition_path, scfc_file, env):
        if env == 'fsmf':
            if scfc_file and self._is_only_one_file(scfc_file):
                return scfc_file
            else:
                return "{}/config/{}".format(partition_path, self._get_scfc_name(partition_path))
        elif env == 'fzm':
            return "{}/btsom/config/active/bts.xml".format(partition_path) if scfc_file == '' else scfc_file

    def _find_scfc_paths(self, partition_path, env='fsmf'):
        if env == 'fsmf':
            return 'ls {}/config/SCFC_*.xml'.format(partition_path)
        elif env == 'fzm':
            return 'ls {}/btsom/config/active/bts.xml'.format(partition_path)

    def _get_scfc_full_path(self, partition_path, scfc_name=None, env='fsmf'):
        if env == 'fsmf':
            return '{}/config/{}'.format(partition_path, scfc_name)
        elif env == 'fzm':
            return partition_path

    def _get_scfc_name(self, partition_path, env='fsmf'):
        if env == 'fsmf':
            filedirectory_xml = self._get_filedirectory_xml(partition_path)
            root = etree.fromstring(str(filedirectory_xml) if "encoding=" in filedirectory_xml else filedirectory_xml)
            scfc_element = root.find("fileElement[@name='SCFC']")
            return scfc_element.attrib['name'] + scfc_element.attrib['version']
